 FOR patch IN SELECT value FROM jsonb_array_elements('[{"start_byte":524,"delete_bytes":24,"old_sha256":"15468cf75b3759fed04ad58772b6469a047bf6137c4565a996f031f74be925f4","new_text":"repair_attributes jsonb; signing_prepare_before jsonb;"},{"start_byte":208248,"delete_bytes":0,"old_sha256":"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855","new_text":",{\"acl\":[{\"grantee\":\"postgres\",\"grantable\":false,\"privilege\":\"EXECUTE\"},{\"grantee\":\"service_role\",\"grantable\":false,\"privilege\":\"EXECUTE\"}],\"kind\":\"f\",\"owner\":\"postgres\",\"config\":[\"search_path=public, private, extensions, pg_temp\"],\"strict\":false,\"returns\":\"jsonb\",\"argmodes\":null,\"argnames\":[\"p_company_id\",\"p_customer_id\",\"p_contract_id\",\"p_token_hash\",\"p_recipient_email\",\"p_expires_at\",\"p_actor_user_id\",\"p_channel\"],\"body_md5\":\"cee1222f070383e440a9fd4f71cdf591\",\"defaults\":\"''''internal''''::text\",\"parallel\":\"u\",\"leakproof\":false,\"signature\":\"public.gridex_prepare_customer_contract_signature_request_v1(uuid, uuid, uuid, text, text, timestamp with time zone, uuid, text)\",\"volatility\":\"v\",\"returns_set\":false,\"default_count\":1,\"security_definer\":true}"},{"start_byte":297286,"delete_bytes":0,"old_sha256":"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855","new_text":"\n -- Preserve the source-proven stronger active signature API; never replace it\n -- with its dormant historical predecessor or a simpler canonical body.\n signing_prepare_before:=(SELECT to_jsonb(p) FROM pg_proc p WHERE p.oid=to_regprocedure(''public.gridex_prepare_customer_contract_signature_request_v1(uuid, uuid, uuid, text, text, timestamp with time zone, uuid, text)''));\n IF signing_prepare_before->>''prosrc'' IS NOT NULL AND md5(signing_prepare_before->>''prosrc'')=''cee1222f070383e440a9fd4f71cdf591'' THEN\n  IF NOT EXISTS(SELECT FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=to_regprocedure(''public.gridex_prepare_customer_contract_signature_request_v1(uuid, uuid, uuid, text, text, timestamp with time zone, uuid, text)'')\n   AND md5(pg_get_functiondef(p.oid))=''0e6cbec5c3c542330d33e88be75ed060''\n   AND p.proowner=(SELECT oid FROM pg_roles WHERE rolname=''postgres'') AND p.prokind=''f''\n   AND p.proacl=ARRAY[''postgres=X/postgres'',''service_role=X/postgres'']::aclitem[]\n   AND p.proargtypes=ARRAY[''uuid''::regtype::oid,''uuid''::regtype::oid,''uuid''::regtype::oid,''text''::regtype::oid,''text''::regtype::oid,''timestamptz''::regtype::oid,''uuid''::regtype::oid,''text''::regtype::oid]::oidvector\n   AND p.pronargs=8 AND p.proallargtypes IS NULL AND p.proargmodes IS NULL AND p.proargnames=ARRAY[''p_company_id'',''p_customer_id'',''p_contract_id'',''p_token_hash'',''p_recipient_email'',''p_expires_at'',''p_actor_user_id'',''p_channel'']::text[]\n   AND p.prorettype=''jsonb''::regtype AND NOT p.proretset AND p.pronargdefaults=1 AND pg_get_expr(p.proargdefaults,0)=''''''internal''''::text''\n   AND p.prosecdef AND NOT p.proisstrict AND NOT p.proleakproof AND p.provolatile=''v'' AND p.proparallel=''u''\n   AND p.proconfig=ARRAY[''search_path=public, private, extensions, pg_temp'']::text[] AND l.lanname=''plpgsql''\n   AND p.procost=100 AND p.prorows=0 AND p.provariadic=0 AND p.prosupport=0 AND p.protrftypes IS NULL AND p.probin IS NULL AND p.prosqlbody IS NULL)\n  THEN RAISE EXCEPTION ''ops_strong_active_signing_full_metadata_required''; END IF;\n END IF;\n"},{"start_byte":554266,"delete_bytes":32,"old_sha256":"b85897d6983d4b4e3d5ea71a067b22e009222ba50752566a0a9943da2bbde4f1","new_text":"142b1cc7c5bb71ec7ee14c7d3041cb66"},{"start_byte":721570,"delete_bytes":32,"old_sha256":"b85897d6983d4b4e3d5ea71a067b22e009222ba50752566a0a9943da2bbde4f1","new_text":"142b1cc7c5bb71ec7ee14c7d3041cb66"},{"start_byte":858325,"delete_bytes":454,"old_sha256":"f453b210473f25064cebec74f97f5e60c0b07a5488f93ef51e8fe08eafd9efcc","new_text":"IF coalesce((SELECT md5(prosrc) FROM pg_proc WHERE oid=to_regprocedure(''public.gridex_prepare_customer_contract_signature_request_v1(uuid, uuid, uuid, text, text, timestamp with time zone, uuid, text)'')),''absent'') NOT IN (''8bd61eb144c72df71c050350a6ed0e57'',''cee1222f070383e440a9fd4f71cdf591'') THEN RAISE EXCEPTION ''ops_native_existing_function_drift: %'', ''public.gridex_prepare_customer_contract_signature_request_v1(uuid, uuid, uuid, text, text, timestamp with time zone, uuid, text)''; END IF;\n"},{"start_byte":2227855,"delete_bytes":1262,"old_sha256":"6102a3a666f449d234831015b43ab4efa3b48645565eb2c70cf2f8a53acf3dba","new_text":"\nDECLARE r gridex_ediel_retention.blob_reviews%rowtype;claims jsonb;observed_at timestamptz;BEGIN\n LOCK TABLE public.permissions,public.roles,public.user_roles,public.role_permissions,public.user_permissions,public.user_permission_overrides IN SHARE MODE;\n SELECT * INTO r FROM gridex_ediel_retention.blob_reviews WHERE decision_id=d.id ORDER BY created_at DESC,id DESC LIMIT 1 FOR SHARE;\n PERFORM public.ediel_retention_lock_auth_actor_v1(r.actor_user_id);PERFORM id FROM public.user_profiles WHERE id=r.actor_user_id FOR SHARE;PERFORM user_id FROM public.company_memberships WHERE company_id=d.company_id AND user_id=r.actor_user_id FOR SHARE;\n IF r.outcome IS DISTINCT FROM ''approved'' OR NOT public.ediel_retention_lock_auth_actor_v1(r.actor_user_id) OR NOT EXISTS(SELECT FROM public.user_profiles WHERE id=r.actor_user_id AND user_status=''active'') OR NOT EXISTS(SELECT FROM public.company_memberships WHERE company_id=d.company_id AND user_id=r.actor_user_id AND status=''active'' AND is_active AND accepted_at IS NOT NULL) OR gridex_ediel_retention.permission_v1(d.company_id,r.actor_user_id,''ediel.retention.review'') IS NOT TRUE THEN RETURN NULL;END IF;\n IF gridex_ediel_retention.class_permission_v1(d.company_id,r.actor_user_id,d.retention_class) IS NOT TRUE THEN RETURN NULL;END IF;claims:=gridex_ediel_retention.blob_receipt_v1(d);\n IF r.outcome IS DISTINCT FROM ''approved'' OR NOT public.ediel_retention_lock_auth_actor_v1(r.actor_user_id) OR NOT EXISTS(SELECT FROM public.user_profiles WHERE id=r.actor_user_id AND user_status=''active'') OR NOT EXISTS(SELECT FROM public.company_memberships WHERE company_id=d.company_id AND user_id=r.actor_user_id AND status=''active'' AND is_active AND accepted_at IS NOT NULL) OR gridex_ediel_retention.permission_v1(d.company_id,r.actor_user_id,''ediel.retention.review'') IS NOT TRUE THEN RETURN NULL;END IF;\n IF gridex_ediel_retention.class_permission_v1(d.company_id,r.actor_user_id,d.retention_class) IS NOT TRUE THEN RETURN NULL;END IF;\n observed_at:=clock_timestamp();IF claims IS NULL OR (claims->>''retainUntil'')::timestamptz>observed_at THEN RETURN NULL;END IF;RETURN r.id;\nEND"},{"start_byte":2230288,"delete_bytes":2214,"old_sha256":"04e0067b04f6d00a1b0d401675f957450abbdc47811944498f847c7f60f28873","new_text":"\nDECLARE k gridex_ediel_retention.issuers%rowtype;p jsonb;b bytea;issued timestamptz;expires timestamptz;deadline timestamptz;\nobserved_at timestamptz;BEGIN IF d.document_bytes IS NULL OR encode(sha256(d.document_bytes),''hex'') IS DISTINCT FROM d.document_hash THEN RETURN NULL;END IF;\n IF jsonb_typeof(d.issuer_receipt) IS DISTINCT FROM ''object'' OR coalesce(d.issuer_receipt->>''signatureHex'','''')!~''^[a-f0-9]{64}$'' OR length(coalesce(d.issuer_receipt->>''payloadBase64'','''')) NOT BETWEEN 1 AND 32768 THEN RETURN NULL;END IF;\n SELECT * INTO k FROM gridex_ediel_retention.issuers WHERE id=(d.issuer_receipt->>''issuerId'')::uuid AND company_id=d.company_id FOR SHARE;\n observed_at:=clock_timestamp();\n IF k.id IS NULL OR observed_at<k.valid_from OR observed_at>=k.valid_to OR EXISTS(SELECT FROM gridex_ediel_retention.issuer_revocations WHERE issuer_id=k.id) OR EXISTS(SELECT FROM gridex_ediel_retention.blob_revocations WHERE decision_id=d.id) THEN RETURN NULL;END IF;\n b:=decode(d.issuer_receipt->>''payloadBase64'',''base64'');IF encode(gridex_requested_changes.receipt_hmac_sha256_v1(b,k.signing_key),''hex'') IS DISTINCT FROM d.issuer_receipt->>''signatureHex'' THEN RETURN NULL;END IF;\n p:=convert_from(b,''UTF8'')::jsonb;issued:=(p->>''issuedAt'')::timestamptz;expires:=(p->>''expiresAt'')::timestamptz;deadline:=(p->>''retainUntil'')::timestamptz;\n IF p->>''format'' IS DISTINCT FROM ''ediel_blob_retention_policy_v1'' OR p->>''retentionClass'' IS DISTINCT FROM d.retention_class OR p->>''companyId'' IS DISTINCT FROM d.company_id::text OR p->>''targetId'' IS DISTINCT FROM d.target_id::text OR p->>''messageId'' IS DISTINCT FROM d.message_id::text OR p->>''sourceHash'' IS DISTINCT FROM d.source_hash OR p->>''targetHash'' IS DISTINCT FROM d.target_hash OR p->>''documentHash'' IS DISTINCT FROM d.document_hash OR p->>''issuerLegalReference'' IS DISTINCT FROM k.legal_reference OR nullif(p->>''legalBasisReference'','''') IS NULL OR isfinite(issued) IS DISTINCT FROM true OR isfinite(expires) IS DISTINCT FROM true OR isfinite(deadline) IS DISTINCT FROM true OR issued>observed_at OR expires<=observed_at OR issued<k.valid_from OR expires>k.valid_to THEN RETURN NULL;END IF;RETURN p;\nEXCEPTION WHEN invalid_text_representation OR invalid_parameter_value OR datetime_field_overflow OR character_not_in_repertoire THEN RETURN NULL;\nEND"},{"start_byte":2310829,"delete_bytes":259,"old_sha256":"95e4a8162e11895f18cd415723f636781c8075a3216154c41a2b1cd1ba9832ab","new_text":"\nBEGIN IF TG_OP=''UPDATE'' THEN IF pg_catalog.has_function_privilege(current_user,''public.ediel_is_qualified_finance_retention_transition_v1(text,text,jsonb,jsonb)'',''EXECUTE'') THEN IF public.ediel_is_qualified_finance_retention_transition_v1(TG_TABLE_SCHEMA,TG_TABLE_NAME,to_jsonb(OLD),to_jsonb(NEW)) IS TRUE THEN RETURN NEW;END IF;END IF;END IF;\n  RAISE EXCEPTION ''received_source_evidence_is_append_only'' USING ERRCODE = ''23514'';\nEND\n"},{"start_byte":2311558,"delete_bytes":692,"old_sha256":"da58ba2a91fb0a486573851bc3237ad037619a4a3a6e96de610865181d6ea490","new_text":"\nBEGIN IF TG_OP=''UPDATE'' THEN IF pg_catalog.has_function_privilege(current_user,''public.ediel_is_qualified_finance_retention_transition_v1(text,text,jsonb,jsonb)'',''EXECUTE'') THEN IF public.ediel_is_qualified_finance_retention_transition_v1(TG_TABLE_SCHEMA,TG_TABLE_NAME,to_jsonb(OLD),to_jsonb(NEW)) IS TRUE THEN RETURN NEW;END IF;END IF;END IF;\n  if old.billing_configuration_snapshot_sha256 is not null\n     and (\n       new.billing_configuration_snapshot is distinct from old.billing_configuration_snapshot\n       or new.billing_configuration_snapshot_sha256 is distinct from old.billing_configuration_snapshot_sha256\n       or new.billing_configuration_snapshotted_at is distinct from old.billing_configuration_snapshotted_at\n     ) then\n    raise exception ''billing_configuration_snapshot_is_immutable''\n      using errcode = ''23514'';\n  end if;\n  return new;\nend;\n"},{"start_byte":2312720,"delete_bytes":2219,"old_sha256":"27341fc4221ee6bc39d34cc27956ff89562a5b8319c8672db20da7cafa1c86fb","new_text":"\ndeclare\n  protected boolean;\nBEGIN IF TG_OP=''UPDATE'' THEN IF pg_catalog.has_function_privilege(current_user,''public.ediel_is_qualified_finance_retention_transition_v1(text,text,jsonb,jsonb)'',''EXECUTE'') THEN IF public.ediel_is_qualified_finance_retention_transition_v1(TG_TABLE_SCHEMA,TG_TABLE_NAME,to_jsonb(OLD),to_jsonb(NEW)) IS TRUE THEN RETURN NEW;END IF;END IF;END IF;\n  if coalesce(current_setting(''app.gridex_billing_maintenance'', true), '''') = ''on'' then\n    if tg_op = ''DELETE'' then\n      return old;\n    end if;\n    return new;\n  end if;\n\n  protected := old.status in (''sent'', ''credited'');\n\n  if tg_op = ''DELETE'' then\n    if protected then\n      raise exception ''Skickade/krediterade fakturaexportposter kan inte raderas (item %). Skapa kredit eller korrigering i stället.'', old.id\n        using errcode = ''P0001'';\n    end if;\n    return old;\n  end if;\n\n  if not protected then\n    return new;\n  end if;\n\n  -- Block re-send: status must never go back to a sendable state.\n  if new.status in (''pending'', ''failed'', ''failed_retryable'') then\n    raise exception ''Fakturaexportpost % är redan skickad och kan inte skickas om. Skapa kredit eller korrigering i stället.'', old.id\n      using errcode = ''P0001'';\n  end if;\n\n  -- Block financial mutation of a sent invoice.\n  if new.amount_ex_vat is distinct from old.amount_ex_vat\n     or new.vat_amount is distinct from old.vat_amount\n     or new.amount_inc_vat is distinct from old.amount_inc_vat\n     or new.rounding_amount is distinct from old.rounding_amount\n     or new.request_payload is distinct from old.request_payload\n     or new.idempotency_key is distinct from old.idempotency_key\n     or new.pricing_run_id is distinct from old.pricing_run_id\n     or new.billing_underlay_id is distinct from old.billing_underlay_id\n     or new.customer_id is distinct from old.customer_id\n  then\n    raise exception ''Fakturaexportpost % är skickad och får inte ändras finansiellt. Skapa kredit eller korrigering i stället.'', old.id\n      using errcode = ''P0001'';\n  end if;\n\n  -- Provider invoice identity may be set once but never rewritten.\n  if old.provider_invoice_guid is not null\n     and new.provider_invoice_guid is distinct from old.provider_invoice_guid\n  then\n    raise exception ''Fakturaexportpost % har redan ett leverantörs-id och det får inte skrivas om.'', old.id\n      using errcode = ''P0001'';\n  end if;\n\n  return new;\nend;\n"},{"start_byte":2315409,"delete_bytes":4020,"old_sha256":"f293a102a17cc0afe6a8254807fddb54781515900dd72ecbf0f19eb042d25418","new_text":"\nBEGIN IF TG_OP=''UPDATE'' THEN IF pg_catalog.has_function_privilege(current_user,''public.ediel_is_qualified_finance_retention_transition_v1(text,text,jsonb,jsonb)'',''EXECUTE'') THEN IF public.ediel_is_qualified_finance_retention_transition_v1(TG_TABLE_SCHEMA,TG_TABLE_NAME,to_jsonb(OLD),to_jsonb(NEW)) IS TRUE THEN RETURN NEW;END IF;END IF;END IF;\n  if tg_op = ''UPDATE'' and old.status in (''issued'', ''sent'', ''exported'', ''paid'') and (\n    new.portfolio_id is distinct from old.portfolio_id\n    or new.customer_contract_id is distinct from old.customer_contract_id\n    or new.price_plan_version_id is distinct from old.price_plan_version_id\n    or new.portfolio_monthly_settlement_id is distinct from old.portfolio_monthly_settlement_id\n    or new.portfolio_settlement_revision is distinct from old.portfolio_settlement_revision\n    or new.portfolio_settlement_sha256 is distinct from old.portfolio_settlement_sha256\n    or new.portfolio_settlement_snapshot is distinct from old.portfolio_settlement_snapshot\n    or new.portfolio_price_area_code is distinct from old.portfolio_price_area_code\n    or new.portfolio_delivery_month is distinct from old.portfolio_delivery_month\n    or new.portfolio_price_ore_per_kwh is distinct from old.portfolio_price_ore_per_kwh\n    or new.portfolio_management_fee_ore_per_kwh is distinct from old.portfolio_management_fee_ore_per_kwh\n    or new.portfolio_gross_energy_cost_sek is distinct from old.portfolio_gross_energy_cost_sek\n    or new.portfolio_energy_volume_kwh is distinct from old.portfolio_energy_volume_kwh\n    or new.delivery_month is distinct from old.delivery_month\n    or new.price_area_code is distinct from old.price_area_code\n    or new.consumption_kwh is distinct from old.consumption_kwh\n    or new.portfolio_share_percent is distinct from old.portfolio_share_percent\n    or new.spot_share_percent is distinct from old.spot_share_percent\n    or new.fixed_share_percent is distinct from old.fixed_share_percent\n    or new.fixed_price_sek_per_kwh is distinct from old.fixed_price_sek_per_kwh\n    or new.portfolio_energy_cost_sek is distinct from old.portfolio_energy_cost_sek\n    or new.spot_energy_cost_sek is distinct from old.spot_energy_cost_sek\n    or new.fixed_energy_cost_sek is distinct from old.fixed_energy_cost_sek\n    or new.management_fee_sek is distinct from old.management_fee_sek\n    or new.other_fees_sek is distinct from old.other_fees_sek\n    or new.vat_rate is distinct from old.vat_rate\n    or new.calculation_snapshot is distinct from old.calculation_snapshot\n    or new.calculation_snapshot_sha256 is distinct from old.calculation_snapshot_sha256\n  ) then\n    raise exception using errcode = ''55000'', message = ''issued_invoice_portfolio_evidence_immutable'';\n  end if;\n\n  if new.status in (''issued'', ''sent'', ''exported'', ''paid'')\n     and new.portfolio_id is not null\n     and (\n       new.portfolio_monthly_settlement_id is null\n       or new.portfolio_settlement_status <> ''locked''\n       or nullif(new.portfolio_settlement_sha256, '''') is null\n       or coalesce(new.portfolio_settlement_snapshot, ''{}''::jsonb) = ''{}''::jsonb\n       or new.customer_contract_id is null\n       or new.price_plan_version_id is null\n       or new.delivery_month is null\n       or new.price_area_code is null\n       or new.consumption_kwh is null\n       or new.portfolio_share_percent is null\n       or new.spot_share_percent is null\n       or new.fixed_share_percent is null\n       or abs(\n         new.portfolio_share_percent\n         + new.spot_share_percent\n         + new.fixed_share_percent\n         - 100\n       ) > 0.000001\n       or new.portfolio_energy_cost_sek is null\n       or new.spot_energy_cost_sek is null\n       or new.fixed_energy_cost_sek is null\n       or (new.fixed_share_percent > 0 and new.fixed_price_sek_per_kwh is null)\n       or new.management_fee_sek is null\n       or new.other_fees_sek is null\n       or new.vat_rate is null\n       or nullif(new.calculation_snapshot_sha256, '''') is null\n       or coalesce(new.calculation_snapshot, ''{}''::jsonb) = ''{}''::jsonb\n     ) then\n    raise exception using errcode = ''23514'', message = ''final_invoice_requires_locked_portfolio_settlement_evidence'';\n  end if;\n  return new;\nend "},{"start_byte":2319911,"delete_bytes":1034,"old_sha256":"9b5cc89ede4d7142b56674ec5884ca8c9c35b9ca2ca7326e3d24c8ffc1a99dec","new_text":"\nBEGIN IF TG_OP=''UPDATE'' THEN IF pg_catalog.has_function_privilege(current_user,''public.ediel_is_qualified_finance_retention_transition_v1(text,text,jsonb,jsonb)'',''EXECUTE'') THEN IF public.ediel_is_qualified_finance_retention_transition_v1(TG_TABLE_SCHEMA,TG_TABLE_NAME,to_jsonb(OLD),to_jsonb(NEW)) IS TRUE THEN RETURN NEW;END IF;END IF;END IF;\n IF EXISTS(SELECT FROM gridex_billing_source.underlay_bindings WHERE underlay_id=old.id) AND (tg_op=''DELETE'' OR\n  ROW(new.company_id,new.customer_id,new.metering_point_id,new.supply_period_id,new.contract_id,new.pricing_snapshot_id,new.contract_price_snapshot_id,new.total_kwh,new.billing_period_start,new.billing_period_end,new.payload,new.pricing_snapshot,new.energy_direction,new.settlement_type)\n  IS DISTINCT FROM ROW(old.company_id,old.customer_id,old.metering_point_id,old.supply_period_id,old.contract_id,old.pricing_snapshot_id,old.contract_price_snapshot_id,old.total_kwh,old.billing_period_start,old.billing_period_end,old.payload,old.pricing_snapshot,old.energy_direction,old.settlement_type)) THEN RAISE EXCEPTION ''billing_source_finalized_underlay_immutable'' USING ERRCODE=''55000''; END IF;\n RETURN CASE WHEN tg_op=''DELETE'' THEN old ELSE new END;\nEND "},{"start_byte":2321415,"delete_bytes":2102,"old_sha256":"d27739fd9f36c7570deffbcfe0db4f5ab8d5dd53cc3fff57b2beb8089be30b43","new_text":"\nBEGIN IF TG_OP=''UPDATE'' THEN IF pg_catalog.has_function_privilege(current_user,''public.ediel_is_qualified_finance_retention_transition_v1(text,text,jsonb,jsonb)'',''EXECUTE'') THEN IF public.ediel_is_qualified_finance_retention_transition_v1(TG_TABLE_SCHEMA,TG_TABLE_NAME,to_jsonb(OLD),to_jsonb(NEW)) IS TRUE THEN RETURN NEW;END IF;END IF;END IF;\n  if tg_op=''DELETE'' then raise exception using errcode=''55000'',message=''portfolio_settlement_append_only''; end if;\n  if old.status<>new.status and not (\n    (old.status=''draft'' and new.status=''calculated'')\n    or (old.status=''calculated'' and new.status=''reviewed'')\n    or (old.status=''reviewed'' and new.status=''final'')\n    or (old.status=''final'' and new.status=''locked'')\n  ) then\n    raise exception using errcode=''23514'',message=''invalid_portfolio_settlement_transition'';\n  end if;\n  if new.status in(''final'',''locked'') and (\n    new.portfolio_price_ore_per_kwh is null\n    or new.calculation_snapshot_sha256 is null\n    or new.calculated_at is null or new.reviewed_at is null or new.approved_at is null\n  ) then\n    raise exception using errcode=''23514'',message=''portfolio_settlement_final_evidence_incomplete'';\n  end if;\n  if old.status=''locked'' and not (\n    coalesce(current_setting(''gridex.portfolio_correction_write'',true),'''')=''on''\n    and new.is_current=false and new.superseded_by_settlement_id is not null\n    and (to_jsonb(new)-''is_current''-''superseded_by_settlement_id'')=(to_jsonb(old)-''is_current''-''superseded_by_settlement_id'')\n  ) then\n    raise exception using errcode=''55000'',message=''locked_portfolio_settlement_immutable'';\n  end if;\n  if old.status=''final'' and not (\n    (\n      new.status=''locked''\n      and (to_jsonb(new)-''status''-''locked_by''-''locked_at'')\n        =(to_jsonb(old)-''status''-''locked_by''-''locked_at'')\n    ) or (\n      coalesce(current_setting(''gridex.portfolio_correction_write'',true),'''')=''on''\n      and new.status=''final'' and new.is_current=false\n      and new.superseded_by_settlement_id is not null\n      and (to_jsonb(new)-''is_current''-''superseded_by_settlement_id'')\n        =(to_jsonb(old)-''is_current''-''superseded_by_settlement_id'')\n    )\n  ) then\n    raise exception using errcode=''55000'',message=''final_portfolio_settlement_immutable_create_correction_revision'';\n  end if;\n  return new;\nend "},{"start_byte":2324018,"delete_bytes":2903,"old_sha256":"3e534a1c664b0bdb8e9fe5ad9b5e4247b1d29bb0a7955ff0dc25a35d65282f7b","new_text":"\nDECLARE issuer gridex_ediel_retention.issuers%rowtype;p jsonb;bytes bytea;issued timestamptz;expires timestamptz;deadline timestamptz;journal_end timestamptz;operation text;observed_at timestamptz;BEGIN IF d.document_bytes IS NULL OR encode(sha256(d.document_bytes),''hex'') IS DISTINCT FROM d.document_hash THEN RETURN NULL;END IF;\n IF jsonb_typeof(d.issuer_receipt) IS DISTINCT FROM ''object'' OR coalesce(d.issuer_receipt->>''signatureHex'','''')!~''^[a-f0-9]{64}$'' OR length(coalesce(d.issuer_receipt->>''payloadBase64'','''')) NOT BETWEEN 1 AND 32768 THEN RETURN NULL;END IF;\n SELECT * INTO issuer FROM gridex_ediel_retention.issuers WHERE id=(d.issuer_receipt->>''issuerId'')::uuid AND company_id=d.company_id FOR SHARE;\n observed_at:=clock_timestamp();\n IF issuer.id IS NULL OR observed_at<issuer.valid_from OR observed_at>=issuer.valid_to OR EXISTS(SELECT FROM gridex_ediel_retention.issuer_revocations WHERE issuer_id=issuer.id) OR EXISTS(SELECT FROM gridex_ediel_retention.finance_revocations WHERE decision_id=d.id) THEN RETURN NULL;END IF;\n bytes:=decode(d.issuer_receipt->>''payloadBase64'',''base64'');IF encode(gridex_requested_changes.receipt_hmac_sha256_v1(bytes,issuer.signing_key),''hex'') IS DISTINCT FROM d.issuer_receipt->>''signatureHex'' THEN RETURN NULL;END IF;\n p:=convert_from(bytes,''UTF8'')::jsonb;issued:=(p->>''issuedAt'')::timestamptz;expires:=(p->>''expiresAt'')::timestamptz;deadline:=(p->>''retainUntil'')::timestamptz;journal_end:=(p->>''journalRetainUntil'')::timestamptz;\n SELECT x.operation INTO STRICT operation FROM gridex_ediel_retention.finance_class_catalog x WHERE retention_class=d.retention_class;\n IF p->>''format'' IS DISTINCT FROM ''ediel_finance_copy_retention_policy_v1'' OR p->>''retentionClass'' IS DISTINCT FROM d.retention_class OR p->>''targetId'' IS DISTINCT FROM d.target_id OR p->>''companyId'' IS DISTINCT FROM d.company_id::text\n OR p->>''sourceTable'' IS DISTINCT FROM (SELECT source_schema||''.''||source_table FROM gridex_ediel_retention.finance_class_catalog WHERE retention_class=d.retention_class)\n OR p->>''sourceHash'' IS DISTINCT FROM d.source_hash OR p->>''targetHash'' IS DISTINCT FROM d.target_hash OR p->>''scopeHash'' IS DISTINCT FROM d.scope_hash OR p->>''documentHash'' IS DISTINCT FROM d.document_hash OR p->>''operation'' IS DISTINCT FROM operation\n OR p->>''issuerLegalReference'' IS DISTINCT FROM issuer.legal_reference OR nullif(p->>''legalBasisReference'','''') IS NULL OR nullif(p->>''journalPurposeReference'','''') IS NULL OR p->>''accessRevocationRequired'' IS DISTINCT FROM ''true''\n OR isfinite(issued) IS DISTINCT FROM true OR isfinite(expires) IS DISTINCT FROM true OR isfinite(deadline) IS DISTINCT FROM true OR isfinite(journal_end) IS DISTINCT FROM true OR journal_end<=observed_at OR issued>observed_at OR expires<=observed_at OR issued<issuer.valid_from OR expires>issuer.valid_to THEN RETURN NULL;END IF;RETURN p;\nEXCEPTION WHEN invalid_text_representation OR invalid_parameter_value OR datetime_field_overflow OR character_not_in_repertoire THEN RETURN NULL;END"},{"start_byte":2366671,"delete_bytes":2886,"old_sha256":"247abc8c77e4896c5f8210109a1afa2d86229fa0b098517aa3d79b9c2fc55abb","new_text":"\nDECLARE issuer gridex_ediel_retention.issuers%rowtype;p jsonb;bytes bytea;issued timestamptz;expires timestamptz;deadline timestamptz;journal_end timestamptz;operation text;observed_at timestamptz;BEGIN IF d.document_bytes IS NULL OR encode(sha256(d.document_bytes),''hex'') IS DISTINCT FROM d.document_hash THEN RETURN NULL;END IF;\n IF jsonb_typeof(d.issuer_receipt) IS DISTINCT FROM ''object'' OR coalesce(d.issuer_receipt->>''signatureHex'','''')!~''^[a-f0-9]{64}$'' OR length(coalesce(d.issuer_receipt->>''payloadBase64'','''')) NOT BETWEEN 1 AND 32768 THEN RETURN NULL;END IF;\n SELECT * INTO issuer FROM gridex_ediel_retention.issuers WHERE id=(d.issuer_receipt->>''issuerId'')::uuid AND company_id=d.company_id FOR SHARE;\n observed_at:=clock_timestamp();\n IF issuer.id IS NULL OR observed_at<issuer.valid_from OR observed_at>=issuer.valid_to OR EXISTS(SELECT FROM gridex_ediel_retention.issuer_revocations WHERE issuer_id=issuer.id) OR EXISTS(SELECT FROM gridex_ediel_retention.process_revocations WHERE decision_id=d.id) THEN RETURN NULL;END IF;\n bytes:=decode(d.issuer_receipt->>''payloadBase64'',''base64'');IF encode(gridex_requested_changes.receipt_hmac_sha256_v1(bytes,issuer.signing_key),''hex'') IS DISTINCT FROM d.issuer_receipt->>''signatureHex'' THEN RETURN NULL;END IF;\n p:=convert_from(bytes,''UTF8'')::jsonb;issued:=(p->>''issuedAt'')::timestamptz;expires:=(p->>''expiresAt'')::timestamptz;deadline:=(p->>''retainUntil'')::timestamptz;journal_end:=(p->>''journalRetainUntil'')::timestamptz;\n SELECT x.operation INTO STRICT operation FROM gridex_ediel_retention.process_class_catalog x WHERE retention_class=d.retention_class;\n IF p->>''format'' IS DISTINCT FROM ''ediel_process_journal_retention_policy_v1'' OR p->>''retentionClass'' IS DISTINCT FROM d.retention_class OR p->>''targetId'' IS DISTINCT FROM d.target_id OR p->>''companyId'' IS DISTINCT FROM d.company_id::text\n OR p->>''sourceTable'' IS DISTINCT FROM (SELECT source_table FROM gridex_ediel_retention.process_class_catalog WHERE retention_class=d.retention_class)\n OR p->>''sourceHash'' IS DISTINCT FROM d.source_hash OR p->>''targetHash'' IS DISTINCT FROM d.target_hash OR p->>''scopeHash'' IS DISTINCT FROM d.scope_hash OR p->>''documentHash'' IS DISTINCT FROM d.document_hash OR p->>''operation'' IS DISTINCT FROM operation\n OR p->>''issuerLegalReference'' IS DISTINCT FROM issuer.legal_reference OR nullif(p->>''legalBasisReference'','''') IS NULL OR nullif(p->>''journalPurposeReference'','''') IS NULL OR p->>''accessRevocationRequired'' IS DISTINCT FROM ''true''\n OR isfinite(issued) IS DISTINCT FROM true OR isfinite(expires) IS DISTINCT FROM true OR isfinite(deadline) IS DISTINCT FROM true OR isfinite(journal_end) IS DISTINCT FROM true OR journal_end<=observed_at OR issued>observed_at OR expires<=observed_at OR 